real3<T> extent = bmax - bmin;
real3<T> inv_extent = real3<T>(1.0f / extent.x, 1.0f / extent.y, 1.0f / extent.z);

const int num_bins = 16;
real3<int> bin_counts = real3<int>(0);
real3<T> bin_width = extent / static_cast<T>(num_bins);

// Initialize bin data
std::vector<BinBuffer<T>::Bin> bins_x(num_bins);
std::vector<BinBuffer<T>::Bin> bins_y(num_bins);
std::vector<BinBuffer<T>::Bin> bins_z(num_bins);

for (int i = 0; i < num_bins; ++i) {
  bins_x[i] = BinBuffer<T>::Bin();
  bins_y[i] = BinBuffer<T>::Bin();
  bins_z[i] = BinBuffer<T>::Bin();
}

// Bin primitives
for (int i = 0; i < bins->num_primitives; ++i) {
  const T *prim = bins->primitives[i];
  real3<T> center = real3<T>((prim[0] + prim[3]) * 0.5f, (prim[1] + prim[4]) * 0.5f, (prim[2] + prim[5]) * 0.5f);

  // Bin along X
  int bin_x = static_cast<int>((center.x - bmin.x) * inv_extent.x * num_bins);
  bin_x = std::min(std::max(bin_x, 0), num_bins - 1);
  bins_x[bin_x].count++;
  bins_x[bin_x].min = std::min(bins_x[bin_x].min, center.x);
  bins_x[bin_x].max = std::max(bins_x[bin_x].max, center.x);

  // Bin along Y
  int bin_y = static_cast<int>((center.y - bmin.y) * inv_extent.y * num_bins);
  bin_y = std::min(std::max(bin_y, 0), num_bins - 1);
  bins_y[bin_y].count++;
  bins_y[bin_y].min = std::min(bins_y[bin_y].min, center.y);
  bins_y[bin_y].max = std::max(bins_y[bin_y].max, center.y);

  // Bin along Z
  int bin_z = static_cast<int>((center.z - bmin.z) * inv_extent.z * num_bins);
  bin_z = std::min(std::max(bin_z, 0), num_bins - 1);
  bins_z[bin_z].count++;
  bins_z[bin_z].min = std::min(bins_z[bin_z].min, center.z);
  bins_z[bin_z].max = std::max(bins_z[bin_z].max, center.z);
}

// Compute SAH costs for each axis
T min_cost = std::numeric_limits<T>::max();
int best_axis = 0;
real3<T> best_cut_pos = real3<T>(0);

// For each axis
for (int axis = 0; axis < 3; ++axis) {
  std::vector<BinBuffer<T>::Bin>* bins_axis = nullptr;
  if (axis == 0) bins_axis = &bins_x;
  else if (axis == 1) bins_axis = &bins_y;
  else bins_axis = &bins_z;

  // Precompute prefix sums
  std::vector<T> left_area(num_bins);
  std::vector<T> right_area(num_bins);
  std::vector<int> left_count(num_bins);
  std::vector<int> right_count(num_bins);

  // Left prefix: cumulative count and area from left
  left_count[0] = (*bins_axis)[0].count;
  T left_width = bin_width[axis];
  left_area[0] = left_width * (axis == 0 ? extent.y * extent.z : (axis == 1 ? extent.x * extent.z : extent.x * extent.y));

  for (int i = 1; i < num_bins; ++i) {
    left_count[i] = left_count[i - 1] + (*bins_axis)[i].count;
    left_area[i] = left_area[i - 1] + left_width * (axis == 0 ? extent.y * extent.z : (axis == 1 ? extent.x * extent.z : extent.x * extent_y));
  }

  // Right suffix: cumulative count and area from right
  right_count[num_bins - 1] = (*bins_axis)[num_bins - 1].count;
  right_area[num_bins - 1] = left_width * (axis == 0 ? extent.y * extent.z : (axis == 1 ? extent.x * extent.z : extent.x * extent.y));

  for (int i = num_bins - 2; i >= 0; --i) {
    right_count[i] = right_count[i + 1] + (*bins_axis)[i].count;
    right_area[i] = right_area[i + 1] + left_width * (axis == 0 ? extent.y * extent.z : (axis == 1 ? extent.x * extent.z : extent.x * extent.y));
  }

  // Try each possible cut position (between bins)
  for (int i = 1; i < num_bins; ++i) {
    T left_sa = left_area[i - 1];
    T right_sa = right_area[i];
    int left_prims = left_count[i - 1];
    int right_prims = right_count[i];

    if (left_prims == 0 || right_prims == 0) continue;

    T cost = left_sa * left_prims + right_sa * right_prims;
    if (cost < min_cost) {
      min_cost = cost;
      best_axis = axis;
      // Compute cut position as bin boundary
      T bin_min = bmin[axis] + static_cast<T>(i) * bin_width[axis];
      if (axis == 0) best_cut_pos.x = bin_min;
      else if (axis == 1) best_cut_pos.y = bin_min;
      else best_cut_pos.z = bin_min;
    }
  }
}

if (min_cost == std::numeric_limits<T>::max()) return false;

*cut_pos = best_cut_pos;
*minCostAxis = best_axis;
return true;

